import asyncio
import functools
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from typing import Any

# A custom decorator that returns a wrapper object instead of awaiting the result
# This simulates a case where the dependency is wrapped and FastAPI fails to identify it as a coroutine.
class Reawaitable:
    def __init__(self, coro):
        self.coro = coro
    def __await__(self):
        return self.coro.__await__()
    def foo(self):
        return "bar"

def reawaitable(func):
    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs)

    # We want to return a Reawaitable object if it's called, 
    # but the issue is about how FastAPI identifies if it SHOULD await it.
    # If FastAPI thinks it's NOT a coroutine, it will just call it and get the result.
    # If the result is a coroutine (or something awaitable), but FastAPI didn't await it,
    # then the result of the dependency will be that awaitable object.

    # To reproduce the issue:
    # 1. The dependency function is wrapped.
    # 2. FastAPI's `is_coroutine_callable` returns False for the wrapper.
    # 3. FastAPI calls the wrapper without awaiting it (if it's not a coroutine).
    # 4. But the wrapper is actually an async function, so it returns a coroutine.
    # 5. The dependency value becomes the coroutine object.
    # 6. The endpoint tries to use the dependency value and fails.

    return wrapper

# Let's use a simpler reproduction: just a wrapped async function.
# If FastAPI doesn't recognize it as a coroutine, it will call it and get a coroutine object.

async def get_foo():
    return {"foo": "bar"}

# Wrap it with something that preserves __wrapped__ but might hide iscoroutinefunction
def simple_wrap(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

# Actually, @functools.cache on an async function returns a regular function that returns a coroutine.
# Let's try that.

app = FastAPI()

@functools.cache
async def cached_dep():
    return {"foo": "bar"}

@app.get("/")
async def root(dep=Depends(cached_dep)):
    return dep["foo"]

client = TestClient(app)

def test_cached_dep():
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == "bar"

if __name__ == "__main__":
    try:
        test_cached_dep()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
